const httpItem = $input.first();
const rawHtml = (httpItem && httpItem.json && httpItem.json.data) ? String(httpItem.json.data) : '';
const html = rawHtml.toLowerCase();

const input = $('Set Website URL').first().json || {};
const websiteUrl = input.website_url || '';

const has = (patterns) => patterns.some(p => html.includes(p));

const hasGTM = has(['googletagmanager.com', 'gtm-', 'gtag(', 'gtag.js']);
const hasMetaPixel = has(['connect.facebook.net', 'fbevents.js', 'fbq(']);
const hasHotjar = has(['static.hotjar.com', 'hotjar.com', 'hj(', '_hjsettings']);
const hasCookieConsent = has(['cookie-consent', 'cookieconsent', 'cookie consent', 'cookie banner', 'cookiebot', 'onetrust', 'we use cookies', 'accept cookies', 'gdpr']);

const trackers = [];
if (hasGTM) trackers.push('Google Tag Manager');
if (hasMetaPixel) trackers.push('Meta Pixel');
if (hasHotjar) trackers.push('Hotjar');

// Derive origin (scheme + host) from the website URL
let origin = websiteUrl.trim().replace(/\/+$/, '');
const schemeMatch = origin.match(/^(https?:\/\/[^/]+)/i);
origin = schemeMatch ? schemeMatch[1] : ('https://' + origin.replace(/^https?:\/\//i, '').split('/')[0]);

const resolveUrl = (input) => {
  const raw = String(input || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.indexOf('//') === 0) return 'https:' + raw;
  if (raw.charAt(0) === '/') return origin + raw;
  return origin + '/' + raw;
};

// Find the privacy-policy link in the raw HTML. Prefer a page linked as
// "Privacy Policy" (or data protection).
let privacyAnchorUrl = '';
let dataProtectionAnchorUrl = '';
const anchorRegex = /<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = anchorRegex.exec(rawHtml)) !== null) {
  const href = m[1] || '';
  const inner = (m[2] || '').toLowerCase();
  const hrefLower = href.toLowerCase();
  const isPrivacy = /privacy/.test(hrefLower) || /privacy/.test(inner);
  const isDataProtection = /data-protection|data_protection/.test(hrefLower) || /data protection|personal data/.test(inner);
  if (isPrivacy) {
    if (!privacyAnchorUrl) privacyAnchorUrl = resolveUrl(href);
    break;
  }
  if (isDataProtection && !dataProtectionAnchorUrl) {
    dataProtectionAnchorUrl = resolveUrl(href);
  }
}
const anchorPolicyUrl = privacyAnchorUrl || dataProtectionAnchorUrl;

const textMentionsPolicy = has(['privacy-policy', 'privacy policy', 'privacypolicy', '/privacy', 'data protection', 'personal data']);

// Build the list of URLs to fetch. If a real anchor link was found, trust it.
// Otherwise fall back to common privacy-policy paths.
let candidates;
if (anchorPolicyUrl) {
  candidates = [anchorPolicyUrl];
} else {
  const commonPaths = ['/privacy-policy', '/privacy', '/privacy-notice', '/legal/privacy', '/pages/privacy-policy', '/policies/privacy-policy', '/data-protection'];
  candidates = commonPaths.map(p => origin + p);
}

const totalCandidates = candidates.length;
return candidates.map((url, idx) => ({
  json: {
    website_url: websiteUrl,
    trackers: trackers,
    has_cookie_consent: hasCookieConsent,
    text_mentions_policy: textMentionsPolicy,
    has_anchor: anchorPolicyUrl !== '',
    candidate_index: idx,
    total_candidates: totalCandidates,
    fetch_url: url,
  },
}));

const base = $('Analyze Homepage Content').first().json;
const websiteUrl = base.website_url || '';
const trackers = base.trackers || [];
const hasTrackers = trackers.length > 0;
const hasCookieConsent = !!base.has_cookie_consent;
const textMentionsPolicy = !!base.text_mentions_policy;
const hasAnchor = !!base.has_anchor;

// Inspect every fetched candidate page and pick the first that genuinely looks
// like a privacy policy (real content, not a soft-404 or empty shell).
const fetched = $input.all();
const analyzeItems = $('Analyze Homepage Content').all();

const extractText = (rawHtml) => String(rawHtml || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const looksLikePolicy = (text) => {
  const t = text.toLowerCase();
  if (text.length < 500) return false; // too short - likely a 404 / empty shell
  const isNotFound = /(^|\W)404(\W|$)|page not found|page you (were|are) looking for|does\s?n.?t exist|could\s?n.?t be found/.test(t);
  if (isNotFound) return false;
  const mentionsPrivacy = /(privacy|personal data|data protection|personal information)/.test(t);
  return mentionsPrivacy;
};

let policyText = '';
let policyUrl = '';
for (let i = 0; i < fetched.length; i++) {
  const it = fetched[i];
  const data = (it && it.json && it.json.data) ? it.json.data : '';
  const text = extractText(data);
  if (looksLikePolicy(text)) {
    policyText = text;
    policyUrl = (analyzeItems[i] && analyzeItems[i].json) ? analyzeItems[i].json.fetch_url : '';
    break;
  }
}

const policyFound = policyText !== '';
const canGrade = policyFound;
const hasPrivacyPolicy = policyFound || hasAnchor || textMentionsPolicy;

// ---- Site-level compliance score (presence checks) ----
let siteScore = 100;
const gaps = [];

if (!hasPrivacyPolicy) {
  siteScore -= 35;
  gaps.push('No Privacy Policy or data protection notice link was found on the page.');
}
if (!hasCookieConsent) {
  siteScore -= 30;
  gaps.push('No cookie consent banner was detected.');
}
if (hasTrackers && !hasCookieConsent) {
  siteScore -= 25;
  gaps.push('Tracking scripts (' + trackers.join(', ') + ') load without a cookie consent mechanism, which may process personal data without the data subject\'s consent.');
}
if (hasTrackers && !hasPrivacyPolicy) {
  siteScore -= 10;
  gaps.push('Tracking scripts are present but no Privacy Policy discloses how visitor data is processed.');
}
if (siteScore < 0) siteScore = 0;

const gapCount = gaps.length;
const summaryLine = gapCount === 0
  ? 'No compliance gaps were identified.'
  : (gapCount + (gapCount === 1 ? ' Gap was identified.' : ' Gaps were identified.'));

const gapsForList = gapCount === 0
  ? ['No major site-level compliance gaps detected in this automated scan.']
  : gaps.slice();
const gapsHtml = gapsForList.map(g => '<li style="margin-bottom:8px;">' + g + '</li>').join('');
const gapsHtmlMasked = gapsForList.map(() => '<li style="margin-bottom:8px;">[ Details Available in Full Report ]</li>').join('');

let siteColor = '#e53e3e';
if (siteScore >= 70) siteColor = '#38a169';
else if (siteScore >= 40) siteColor = '#dd6b20';

let siteScoreMessage;
if (siteScore >= 70) siteScoreMessage = "You've built a strong data protection foundation aligned with the AU Convention. A few small refinements will help you stay ahead and keep visitor trust high.";
else if (siteScore >= 40) siteScoreMessage = "You're well on your way, and a handful of focused improvements will strengthen your site's alignment with the AU Data Protection Convention.";
else siteScoreMessage = 'There are a number of improvements needed, some key additions will make a big difference to your site\'s compliance with the AU Data Protection Convention.';

// ---- Privacy Policy Quality grading (keyword heuristic, approximate) ----
// Criteria mapped to the African Union Convention on Cyber Security and
// Personal Data Protection (Malabo Convention) principles and data-subject
// rights (Chapter II, Articles 13-19).
let qualitySectionHtml = '';
let qualitySectionFullHtml = '';
let qualityScore = null;
let qualityBand = 'Not assessed';

if (canGrade) {
  const t = policyText.toLowerCase();
  const test = (re) => re.test(t);

  // 1. Data Controller Identity & Contact Details (weight 10)
  const hasController = test(/data controller|controller|responsible party|data protection officer/);
  const hasEmail = test(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  const hasGenericEmail = test(/(info|support|admin|contact|hello|enquiries|privacy|dpo)@/);
  const hasAddress = test(/postal address|physical address|p\.?o\.? box|street|avenue|\broad\b|building|floor|registered office/);
  let c1 = 0;
  if (hasController && hasEmail && hasAddress) c1 = 2;
  else if (hasController || hasEmail || hasGenericEmail) c1 = 1;

  // 2. Specified & Legitimate Purposes of Processing (weight 15)
  const hasPurpose = test(/purpose(s)? (of|for) (processing|collection)|why we (collect|process)|purpose of processing|for the (specific )?purpose/);
  const hasVaguePurpose = test(/improve (our )?services|general business purposes|business purposes/);
  const hasSpecificPurpose = test(/newsletter|order|delivery|billing|invoic|account|marketing|support|fulfil/);
  let c2 = 0;
  if (hasPurpose && hasSpecificPurpose) c2 = 2;
  else if (hasPurpose || hasVaguePurpose) c2 = 1;

  // 3. Consent & Legitimacy of Processing (weight 15)
  const hasConsent = test(/consent/);
  const hasLegalBasis = test(/legitimate (interest|basis)|legal (basis|obligation|ground)|lawful basis|performance of a contract/);
  const hasOptOut = test(/opt[- ]?out|unsubscribe|withdraw consent|withdraw your consent/);
  let c3 = 0;
  if (hasConsent && (hasLegalBasis || hasOptOut)) c3 = 2;
  else if (hasConsent || hasOptOut) c3 = 1;

  // 4. Data Subject Rights & Supervisory Authority (weight 20)
  let rightsCount = 0;
  if (test(/right to access|request access|right of access/)) rightsCount++;
  if (test(/correct(ion)?|rectif/)) rightsCount++;
  if (test(/delet(e|ion)|erasure/)) rightsCount++;
  if (test(/object(ion)? to (the )?processing|right to object/)) rightsCount++;
  const hasAuthority = test(/data protection authority|supervisory authority|national (data )?protection (authority|commission)|protection authority/);
  let c4 = 0;
  if (rightsCount >= 3 && hasAuthority) c4 = 2;
  else if (rightsCount >= 1) c4 = 1;

  // 5. Cross-Border Data Transfers (weight 15)
  const hasCrossBorder = test(/cross[- ]?border|transborder|outside (the country|africa|the (member )?state)|international(ly)? transfer|transfer.*(abroad|another country)/);
  const hasCloud = test(/cloud|aws|amazon web services|azure|google cloud|servers? (located|hosted)/);
  const hasSafeguard = test(/adequate (level of )?(protection|safeguards)|sufficient (level of )?protection|binding corporate rules|standard contractual|appropriate safeguards/);
  let c5 = 0;
  if (hasCrossBorder && hasSafeguard) c5 = 2;
  else if (hasCrossBorder || hasCloud) c5 = 1;

  // 6. Security, Confidentiality & Data Retention (weight 15)
  const hasSecurity = test(/security (measures|safeguards)|encryption|access control|confidential|technical and organ(i|iz|is)ational/);
  const hasRetentionCriteria = test(/retention (period|schedule)|retain.*(for a period|until|criteria|purpose)|how long we (keep|retain)|securely destroy/);
  const hasVagueRetention = test(/as long as (necessary|needed)|retain (data )?indefinitely/);
  let c6 = 0;
  if (hasSecurity && hasRetentionCriteria) c6 = 2;
  else if (hasSecurity || hasRetentionCriteria || hasVagueRetention) c6 = 1;

  // 7. Plain Language & Transparency (weight 10) - length proxy
  let c7 = 0;
  if (policyText.length > 1500) c7 = 2;
  else if (policyText.length > 300) c7 = 1;

  const criteria = [
    { label: 'Data Controller Identity & Contact Details', weight: 10, points: c1 },
    { label: 'Specified & Legitimate Purposes of Processing', weight: 15, points: c2 },
    { label: 'Consent & Legitimacy of Processing', weight: 15, points: c3 },
    { label: 'Data Subject Rights & Supervisory Authority', weight: 20, points: c4 },
    { label: 'Cross-Border Data Transfers', weight: 15, points: c5 },
    { label: 'Security, Confidentiality & Data Retention', weight: 15, points: c6 },
    { label: 'Plain Language & Transparency', weight: 10, points: c7 },
  ];

  let weighted = 0;
  for (const c of criteria) { weighted += c.weight * c.points; }
  qualityScore = Math.round(weighted / 2);

  let qualityMessage;
  if (qualityScore >= 85) {
    qualityBand = 'Highly Effective & AU Convention Aligned';
    qualityMessage = 'Your privacy policy is thorough and well-aligned with the African Union Data Protection Convention. A light periodic review will keep it current as your business grows.';
  } else if (qualityScore >= 65) {
    qualityBand = 'Above Average';
    qualityMessage = 'Your privacy policy covers the essentials well. Strengthening a few areas will take it from good to fully aligned with the AU Data Protection Convention.';
  } else {
    qualityBand = 'Needs Work';
    qualityMessage = 'Your privacy policy needs a few key updates to align with the AU Data Protection Convention.';
  }

  let qColor = '#e53e3e';
  if (qualityScore >= 85) qColor = '#38a169';
  else if (qualityScore >= 65) qColor = '#dd6b20';

  const rows = criteria.map(function (c, idx) {
    const status = c.points === 2 ? 'Compliant' : (c.points === 1 ? 'Partial' : 'Non-Compliant');
    const sColor = c.points === 2 ? '#38a169' : (c.points === 1 ? '#dd6b20' : '#718096');
    const displayLabel = idx === 0 ? c.label : '[ Available in Full Report ]';
    return '<tr>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;color:#2d3748;">' + displayLabel + '</td>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;color:#718096;text-align:center;">' + c.weight + '%</td>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;text-align:center;"><span style="color:#ffffff;background:' + sColor + ';padding:2px 8px;border-radius:10px;font-size:12px;">' + status + '</span></td>' +
      '</tr>';
  }).join('');

  const policyUrlNote = policyUrl ? ('<p style="font-size:12px;color:#718096;">Policy assessed: <a href="' + policyUrl + '" style="color:#3182ce;">' + policyUrl + '</a></p>') : '';

  qualitySectionHtml =
    '<h2 style="font-size:18px;border-bottom:2px solid #edf2f7;padding-bottom:8px;margin-top:32px;">Privacy Policy Quality Score</h2>' +
    '<div style="text-align:center;margin:0 0 16px;">' +
    '<div style="font-size:40px;font-weight:bold;color:' + qColor + ';">' + qualityScore + '<span style="font-size:20px;color:#a0aec0;">%</span></div>' +
    '<div style="font-size:14px;font-weight:bold;color:' + qColor + ';">' + qualityBand + '</div>' +
    '<p style="font-size:14px;color:#4a5568;line-height:1.5;margin:12px auto 0;max-width:520px;">' + qualityMessage + '</p>' +
    '</div>' + policyUrlNote +
    '<table style="width:100%;border-collapse:collapse;margin-bottom:8px;">' +
    '<thead><tr>' +
    '<th style="text-align:left;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Criterion</th>' +
    '<th style="text-align:center;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Weight</th>' +
    '<th style="text-align:center;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Result</th>' +
    '</tr></thead><tbody>' + rows + '</tbody></table>' +
    '<p style="font-size:11px;color:#a0aec0;">Quality grades are produced by automated keyword analysis of the policy text and are indicative only \u2014 they are not a substitute for a legal review.</p>';

  // Full (unmasked) criterion rows
  const fullRows = criteria.map(function (c) {
    const status = c.points === 2 ? 'Compliant' : (c.points === 1 ? 'Partial' : 'Non-Compliant');
    const sColor = c.points === 2 ? '#38a169' : (c.points === 1 ? '#dd6b20' : '#718096');
    return '<tr>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;color:#2d3748;">' + c.label + '</td>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;color:#718096;text-align:center;">' + c.weight + '%</td>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;text-align:center;">' + c.points + '/2</td>' +
      '<td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px;text-align:center;"><span style="color:#ffffff;background:' + sColor + ';padding:2px 8px;border-radius:10px;font-size:12px;">' + status + '</span></td>' +
      '</tr>';
  }).join('');

  qualitySectionFullHtml =
    '<h2 style="font-size:18px;border-bottom:2px solid #edf2f7;padding-bottom:8px;margin-top:32px;">Privacy Policy Quality Score (Full)</h2>' +
    '<div style="text-align:center;margin:0 0 16px;">' +
    '<div style="font-size:40px;font-weight:bold;color:' + qColor + ';">' + qualityScore + '<span style="font-size:20px;color:#a0aec0;">%</span></div>' +
    '<div style="font-size:14px;font-weight:bold;color:' + qColor + ';">' + qualityBand + '</div>' +
    '<p style="font-size:14px;color:#4a5568;line-height:1.5;margin:12px auto 0;max-width:520px;">' + qualityMessage + '</p>' +
    '</div>' + policyUrlNote +
    '<table style="width:100%;border-collapse:collapse;margin-bottom:8px;">' +
    '<thead><tr>' +
    '<th style="text-align:left;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Criterion</th>' +
    '<th style="text-align:center;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Weight</th>' +
    '<th style="text-align:center;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Score</th>' +
    '<th style="text-align:center;padding:8px;font-size:12px;color:#a0aec0;text-transform:uppercase;">Result</th>' +
    '</tr></thead><tbody>' + fullRows + '</tbody></table>' +
    '<p style="font-size:11px;color:#a0aec0;">Full criterion breakdown. Quality grades are produced by automated keyword analysis and are indicative only.</p>';
} else if (hasPrivacyPolicy) {
  qualitySectionHtml =
    '<h2 style="font-size:18px;border-bottom:2px solid #edf2f7;padding-bottom:8px;margin-top:32px;">Privacy Policy Quality Score</h2>' +
    '<p style="font-size:14px;color:#dd6b20;">A privacy notice appears to be referenced on the site, but no readable policy page could be located at a common path to assess its alignment with the AU Data Protection Convention automatically.</p>';
} else {
  qualitySectionHtml =
    '<h2 style="font-size:18px;border-bottom:2px solid #edf2f7;padding-bottom:8px;margin-top:32px;">Privacy Policy Quality Score</h2>' +
    '<p style="font-size:14px;color:#e53e3e;">No Privacy Policy was found on the website, so an AU Convention quality assessment could not be performed. Publishing a compliant Privacy Policy is the first priority.</p>';
}

if (!qualitySectionFullHtml) { qualitySectionFullHtml = qualitySectionHtml; }

return [{
  json: {
    website_url: websiteUrl,
    score: siteScore,
    score_color: siteColor,
    trackers_detected: trackers,
    has_cookie_consent: hasCookieConsent,
    has_privacy_policy: hasPrivacyPolicy,
    can_grade: canGrade,
    policy_url: policyUrl,
    gap_count: gapCount,
    summary_line: summaryLine,
    site_score_message: siteScoreMessage,
    gaps_html: gapsHtml,
    gaps_html_masked: gapsHtmlMasked,
    quality_score: qualityScore,
    quality_band: qualityBand,
    quality_section_html: qualitySectionHtml,
    quality_section_full_html: qualitySectionFullHtml,
  },
}];
